  "implementation": "def solve(case):
    nodes = case['nodes']
    required_symbols = set(case['required_symbols'])
    node_map = {n['id']: n for n in nodes}
    children_map = {}
    for n in nodes:
        pid = n['parent']
        if pid is not None:
            children_map.setdefault(pid, []).append(n['id'])
    # sort by depth descending, then node id ascending
    sorted_nodes = sorted(nodes, key=lambda n: (-n['depth'], n['id']))
    removed_set = set()
    removed_list = []
    for n in sorted_nodes:
        if n['id'] in removed_set:
            continue
        if not n['removable']:
            continue
        if n['parent'] is None:
            continue
        if n['symbol'] in required_symbols:
            continue
        # check retained children
        children = children_map.get(n['id'], [])
        retained_children = [c for c in children if c not in removed_set]
        if retained_children:
            continue
        # ensure all required symbols still present after removal
        # (although we never remove required-symbol nodes, check for completeness)
        # simulate removal: temporarily remove this node
        temp_retained = {m['id'] for m in nodes} - removed_set - {n['id']}
        missing = [sym for sym in required_symbols if not any(node_map[rid]['symbol'] == sym for rid in temp_retained)]
        if missing:
            continue
        removed_set.add(n['id'])
        removed_list.append(n['id'])
    retained_ids = sorted(n['id'] for n in nodes if n['id'] not in removed_set)
    return {'removed_node_ids': removed_list, 'retained_node_ids': retained_ids}
